  (8, 'Qashqadaryo', 'Кашкадарья', 'Kashkadarya'),
  (9, 'Qoraqalpog''iston', 'Каракалпакстан', 'Karakalpakstan'),
  (10, 'Samarqand', 'Самарканд', 'Samarkand'),
  (11, 'Sirdaryo', 'Сырдарья', 'Syrdarya'),
