insert into crops (id, name_uz, name_ru, name_en, difficulty, water_need, min_water_level, harvest_days_min, harvest_days_max, investment_per_sotka_uzs, yield_kg_per_sotka, price_per_kg_uzs, good_for_consumption, good_for_profit, notes_uz, notes_ru) values
  (1, 'Pomidor', 'Помидор', 'Tomato', 'medium', 'high', 2, 90, 120, 250000, 400, 8000, true, true, 'Issiqsevar. Ko''chat orqali eking, qoziqqa bog''lang, muntazam sug''oring.', 'Теплолюбив. Сажайте рассадой, подвязывайте, регулярно поливайте.'),
  (2, 'Bodring', 'Огурец', 'Cucumber', 'easy', 'high', 2, 50, 70, 200000, 300, 7000, true, true, 'Tez pishadi. Issiqni va namlikni yaxshi ko''radi, ko''p hosil beradi.', 'Быстро созревает. Любит тепло и влагу, обильно плодоносит.'),
  (3, 'Piyoz', 'Лук', 'Onion', 'easy', 'medium', 2, 100, 130, 150000, 350, 4000, true, true, 'Saqlashga qulay, talab doimiy. Quruq joyda yaxshi saqlanadi.', 'Удобен для хранения, спрос стабильный. Хорошо лежит в сухом месте.'),
  (4, 'Sabzi', 'Морковь', 'Carrot', 'easy', 'medium', 2, 70, 100, 120000, 400, 4500, true, true, 'Yumshoq, tozalangan tuproq talab qiladi. Saqlashga chidamli.', 'Нужна рыхлая, очищенная почва. Хорошо хранится.'),
  (5, 'Kartoshka', 'Картофель', 'Potato', 'medium', 'medium', 2, 80, 110, 300000, 250, 5000, true, true, 'Urug''lik tugunak qimmat. Tuproqni tepalab boring, kolorado qo''ng''iziga e''tibor.', 'Семенные клубни дороже. Окучивайте, следите за колорадским жуком.'),
  (6, 'Qalampir', 'Перец', 'Bell pepper', 'medium', 'high', 2, 90, 130, 220000, 200, 10000, true, true, 'Issiqsevar, ko''chat orqali. Bozorda narxi yaxshi.', 'Теплолюбив, сажают рассадой. Хорошая цена на базаре.'),
  (7, 'Karam', 'Капуста', 'Cabbage', 'easy', 'high', 2, 70, 100, 150000, 450, 3500, true, true, 'Ko''p suv talab qiladi. Kuzgi navlar yaxshi saqlanadi.', 'Требует много воды. Осенние сорта хорошо хранятся.'),
  (8, 'Sarimsoq', 'Чеснок', 'Garlic', 'easy', 'medium', 2, 200, 250, 250000, 150, 18000, true, true, 'Kuzda eking, yozda yig''ing. Narxi baland, saqlashga qulay.', 'Сажают осенью, убирают летом. Высокая цена, удобен в хранении.'),
  (9, 'Tarvuz', 'Арбуз', 'Watermelon', 'medium', 'medium', 2, 80, 100, 120000, 300, 3000, true, true, 'Keng joy va issiq kerak. Qumloq tuproqda shirin bo''ladi.', 'Нужно много места и тепла. На песчаной почве слаще.'),
  (10, 'Qovun', 'Дыня', 'Melon', 'medium', 'medium', 2, 80, 110, 130000, 250, 5000, true, true, 'O''zbek qovuni mashhur. Issiq, quyoshli joyda eng shirin.', 'Узбекская дыня знаменита. Слаще всего на жарком солнце.'),
  (11, 'Bug''doy', 'Пшеница', 'Wheat', 'easy', 'low', 1, 210, 260, 80000, 55, 3000, true, false, 'Kam suv talab qiladi, katta maydonga mos. Un uchun o''stiriladi.', 'Мало воды, подходит для больших площадей. Выращивают на муку.'),
  (12, 'Makkajo''xori', 'Кукуруза', 'Corn', 'easy', 'medium', 2, 90, 120, 90000, 120, 4000, true, true, 'Yangi pishgani tez sotiladi. Mol uchun ham foydali.', 'Свежая початка продаётся быстро. Полезна и на корм скоту.'),
  (13, 'Baqlajon', 'Баклажан', 'Eggplant', 'medium', 'high', 2, 100, 130, 200000, 300, 6000, true, true, 'Issiqsevar, ko''chat orqali. Uzoq muddat hosil beradi.', 'Теплолюбив, сажают рассадой. Плодоносит долго.'),
  (14, 'Turp', 'Редис', 'Radish', 'easy', 'low', 1, 25, 40, 80000, 300, 4000, true, false, 'Juda tez pishadi — boshlovchilar uchun ideal. Salqin havoni sevadi.', 'Очень быстро спеет — идеально для новичков. Любит прохладу.'),
  (15, 'Qovoq', 'Тыква', 'Pumpkin', 'easy', 'medium', 1, 90, 120, 90000, 350, 3000, true, false, 'Kam parvarish talab qiladi, uzoq saqlanadi. Keng joy kerak.', 'Неприхотлива, долго хранится. Нужно много места.'),
  (16, 'Loviya', 'Фасоль', 'Beans', 'easy', 'medium', 2, 60, 90, 150000, 120, 15000, true, true, 'Tuproqni azot bilan boyitadi. Quruq loviya narxi yaxshi.', 'Обогащает почву азотом. Сухая фасоль в хорошей цене.'),
  (17, 'Ko''kat (jambil, ukrop)', 'Зелень (укроп, кинза)', 'Herbs & greens', 'easy', 'medium', 2, 30, 50, 100000, 150, 20000, true, true, 'Tez aylanadi, kichik joydan ham daromad. Bir necha marta o''riladi.', 'Быстрый оборот, доход даже с малой площади. Срезается несколько раз.'),
  (18, 'Qulupnay', 'Клубника', 'Strawberry', 'hard', 'high', 3, 60, 90, 400000, 120, 30000, true, true, 'Yuqori daromadli, lekin parvarish talab. Tomchilatib sug''orish tavsiya.', 'Высокодоходна, но требует ухода. Рекомендуется капельный полив.'),
  (19, 'Uzum', 'Виноград', 'Grapes', 'medium', 'medium', 2, 150, 180, 200000, 250, 12000, true, true, 'Ko''p yillik — bir marta eksangiz yillab hosil. Ishkom kerak.', 'Многолетник — посадив раз, плодоносит годами. Нужна шпалера.'),
  (20, 'Kungaboqar', 'Подсолнух', 'Sunflower', 'easy', 'low', 1, 90, 120, 70000, 30, 8000, true, false, 'Kam suv bilan o''sadi. Urug''i va yog''i uchun.', 'Растёт при малом поливе. Ради семечек и масла.')
